using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
public static partial class GardenBoundaryPrefabBuilder {
const string Output="Assets/Scenes/Oasis/GardenPerimeter";
static Mesh SaveMesh(Mesh mesh,string name){mesh.name=name;string path=Output+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;old.uv2=mesh.uv2;old.colors=mesh.colors;old.triangles=mesh.triangles;old.RecalculateBounds();EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
static Mesh FarGlow(float length){var p=new List<Vector3>();var uv=new List<Vector2>();var info=new List<Vector2>();var colors=new List<Color>();var ids=new List<int>();Action<Vector3,Vector3,Vector3,Vector3> q=(a,b,c,d)=>{int k=p.Count;p.AddRange(new[]{a,b,c,d});uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});info.AddRange(Enumerable.Repeat(new Vector2(22,1),4));colors.AddRange(Enumerable.Repeat(new Color(.48f,.31f,.095f),4));ids.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});};float lo=.931f,hi=.956f,z=.04f;q(new Vector3(0,lo,z),new Vector3(length,lo,z),new Vector3(length,hi,z),new Vector3(0,hi,z));q(new Vector3(length,lo,-z),new Vector3(0,lo,-z),new Vector3(0,hi,-z),new Vector3(length,hi,-z));q(new Vector3(0,hi,z),new Vector3(length,hi,z),new Vector3(length,hi,-z),new Vector3(0,hi,-z));var m=new Mesh();m.SetVertices(p);m.SetUVs(0,uv);m.SetUVs(1,info);m.SetColors(colors);m.SetTriangles(ids,0);m.RecalculateNormals();return m;}
static void FenceSide(Transform parent,Vector3 a,Vector3 b,int index,Material mat){float length=Vector3.Distance(a,b);var side=new GameObject("Railing side "+(index+1));side.transform.SetParent(parent,false);side.transform.localPosition=a;side.transform.localRotation=Quaternion.FromToRotation(Vector3.right,(b-a).normalized);var renders=new Renderer[2];for(int lod=0;lod<2;lod++){var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/LandmarkBoundaryFences/Casino Diamonds "+(lod==0?"Near":"Far")+".asset");var end=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/LandmarkBoundaryFences/Casino Diamonds End "+(lod==0?"Near":"Far")+".asset");if(!source||!end)throw new Exception("Casino railing mesh missing");int count=Mathf.CeilToInt(length/8);float segment=length/count;var combine=new List<CombineInstance>();for(int k=0;k<count;k++)combine.Add(new CombineInstance{mesh=source,transform=Matrix4x4.TRS(Vector3.right*(k*segment),Quaternion.identity,new Vector3(segment/8,1,1))});combine.Add(new CombineInstance{mesh=end,transform=Matrix4x4.Translate(Vector3.right*length)});Mesh glow=null;if(lod==1){glow=FarGlow(length);combine.Add(new CombineInstance{mesh=glow,transform=Matrix4x4.identity});}var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(combine.ToArray(),true,true);if(mesh.vertexCount<65535)mesh.indexFormat=IndexFormat.UInt16; // Reassign indices after format change below.
// Index-format changes clear index data in Unity; combine again with final format.
mesh.CombineMeshes(combine.ToArray(),true,true);mesh.RecalculateBounds();if(glow)UnityEngine.Object.DestroyImmediate(glow);var child=new GameObject(lod==0?"Near railing":"Far railing");child.transform.SetParent(side.transform,false);child.AddComponent<MeshFilter>().sharedMesh=SaveMesh(mesh,"Garden Railing Side "+index+" LOD"+lod);var r=child.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;renders[lod]=r;}
var group=side.AddComponent<LODGroup>();group.SetLODs(new[]{new LOD(.022f,new[]{renders[0]}),new LOD(.0025f,new[]{renders[1]})});group.RecalculateBounds();group.localReferencePoint=new Vector3(length/2,.5f,0);group.size=1.05f;var box=side.AddComponent<BoxCollider>();box.center=new Vector3(length/2,.50f,0);box.size=new Vector3(length,1.05f,.30f);}
static Bounds BoundsFor(GameObject obj){var rs=obj.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
static void Palm(Transform parent,GameObject asset,Vector3 point,Vector3 inward,int index){var go=(GameObject)PrefabUtility.InstantiatePrefab(asset,parent);go.name="Perimeter palm "+(index+1);var b=BoundsFor(go);go.transform.localScale*=9/b.size.y;Vector3 lean=new Vector3(b.center.x-go.transform.position.x,0,b.center.z-go.transform.position.z);float yaw=Vector3.SignedAngle(lean.sqrMagnitude>.001f?lean:Vector3.forward,inward,Vector3.up)+(index%3-1)*8;go.transform.localRotation=Quaternion.Euler(0,yaw,0)*go.transform.localRotation;go.transform.localPosition=point;var after=BoundsFor(go);go.transform.position+=Vector3.up*(parent.TransformPoint(point).y-after.min.y);foreach(var c in go.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var l in go.GetComponentsInChildren<Light>(true))UnityEngine.Object.DestroyImmediate(l);foreach(var group in go.GetComponentsInChildren<LODGroup>(true)){var lods=group.GetLODs();if(lods.Length>=3){lods[0].screenRelativeTransitionHeight=.13f;lods[1].screenRelativeTransitionHeight=.045f;lods[2].screenRelativeTransitionHeight=.004f;group.SetLODs(lods);}group.RecalculateBounds();}PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
static void Build(){var sc=SceneManager.GetActiveScene();var plot=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Single(r=>r.name=="polySurface47");var bounds=plot.bounds;float w=bounds.size.x,d=bounds.size.z;Directory.CreateDirectory(Output);AssetDatabase.Refresh();var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas/City Garden Utility Atlas.mat");var palm=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/Art/Vegetation/Prefabs/Palms/DatePalm_01_Prefab.prefab");if(!mat||!palm)throw new Exception("Existing shared assets not found");var root=new GameObject("Garden Perimeter - Palms and Illuminated Railing");float x=w/2-.95f,z=d/2-.95f,gap=4.0f;var corners=new[]{new Vector3(-x,0,-z),new Vector3(x,0,-z),new Vector3(x,0,z),new Vector3(-x,0,z)};int palms=0;try{for(int edge=0;edge<4;edge++){var a=corners[edge];var b=corners[(edge+1)%4];var dir=(b-a).normalized;var start=a+dir*gap;var finish=b-dir*gap;FenceSide(root.transform,start,finish,edge,mat);var inward=Vector3.Cross(dir,Vector3.up).normalized;int count=Mathf.Max(2,Mathf.FloorToInt(Vector3.Distance(start,finish)/15));for(int j=0;j<count;j++){var point=Vector3.Lerp(start,finish,(j+.5f)/count)+inward*3.0f;Palm(root.transform,palm,point,inward,palms++);}}
foreach(var p in corners){var marker=new GameObject("Open corner entrance - 5.6m diagonal clearance");marker.transform.SetParent(root.transform,false);marker.transform.localPosition=p;}
string path=Output+"/Garden Perimeter - Palms and Illuminated Railing.prefab";PrefabUtility.SaveAsPrefabAsset(root,path);AssetDatabase.SaveAssets();Selection.activeObject=AssetDatabase.LoadAssetAtPath<GameObject>(path);EditorGUIUtility.PingObject(Selection.activeObject);root.transform.position=new Vector3(bounds.center.x,bounds.max.y+.02f,bounds.center.z);var ctrl=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool was=ctrl.IsNight;try{foreach(bool n in new[]{false,true}){ctrl.Apply(n);var target=root.transform.position+Vector3.up*2;var cam=target+new Vector3(w*.65f,Mathf.Max(w,d)*.85f,-d*.72f);CityLightingBuilder.Capture(ctrl,Tuple.Create(cam,Quaternion.LookRotation(target-cam)),"Garden-Perimeter-"+(n?"Night":"Day"));var close=root.transform.position+new Vector3(0,2.6f,-z-6);var at=root.transform.position+new Vector3(0,.6f,-z);CityLightingBuilder.Capture(ctrl,Tuple.Create(close,Quaternion.LookRotation(at-close)),"Garden-Railing-"+(n?"Night":"Day"));}}finally{ctrl.Apply(was);}File.WriteAllText("FinalEnvironmentRoadReview/GardenBoundaryPrefab.txt","SUCCESS prefab="+path+" dimensions="+w+"x"+d+" centred pivot at ground. "+palms+" existing DatePalm instances at9m, three palm LODs, four railing sides each near/far combined mesh and shared existing garden material. Existing casino stone/steel/diamond design reused; night-gated top trims and diamonds, distant glow strip retained. Four corner entrances: 4m clear along adjacent edges (~5.6m diagonal), no gate added. Four simple fence colliders, no palm colliders or realtime lights. No new materials/textures/runtime scripts. Garden scene was previewed temporarily; layout not placed/saved in scene. Drag prefab to("+bounds.center.x+","+(bounds.max.y+.02f)+","+bounds.center.z+") for this plot. Existing paths/plants/fountain untouched.");}finally{UnityEngine.Object.DestroyImmediate(root);}}
}

